"""Proposal document model — generated by FR-003 agent."""

import uuid

from sqlalchemy import ForeignKey, Integer, Text
from sqlalchemy.dialects.postgresql import UUID, JSONB
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base, TimestampMixin, UUIDPrimaryKeyMixin


class ProposalDoc(Base, UUIDPrimaryKeyMixin, TimestampMixin):
    """AI-generated event proposal."""

    __tablename__ = "proposal_docs"

    event_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), ForeignKey("event_records.id", ondelete="CASCADE"),
        nullable=False, index=True, unique=True,
    )
    version: Mapped[int] = mapped_column(Integer, default=1, nullable=False)
    sections: Mapped[dict] = mapped_column(JSONB, nullable=False)
    # sections = {
    #   "executive_summary": "...",
    #   "objectives": "...",
    #   "scope": "...",
    #   "schedule": "...",
    #   "resources": "...",
    #   "expected_outcomes": "...",
    #   "risk_assessment": "...",
    #   "appendices": "..."
    # }
    raw_content: Mapped[str | None] = mapped_column(Text, nullable=True)
